-- Joel Frame Work content management schema
create table if not exists public.site_content (
  key text primary key,
  content jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);
alter table public.site_content enable row level security;
drop policy if exists "Public can read site content" on public.site_content;
create policy "Public can read site content" on public.site_content for select using (true);
drop policy if exists "Authenticated admins manage site content" on public.site_content;
create policy "Authenticated admins manage site content" on public.site_content for all to authenticated using (true) with check (true);

insert into storage.buckets (id,name,public,file_size_limit,allowed_mime_types)
values ('joel-site-media','joel-site-media',true,52428800,array['image/jpeg','image/png','image/webp','image/avif','video/mp4','video/webm'])
on conflict (id) do update set public=true, file_size_limit=52428800;
drop policy if exists "Public can view Joel media" on storage.objects;
create policy "Public can view Joel media" on storage.objects for select using (bucket_id='joel-site-media');
drop policy if exists "Authenticated admins upload Joel media" on storage.objects;
create policy "Authenticated admins upload Joel media" on storage.objects for insert to authenticated with check (bucket_id='joel-site-media');
drop policy if exists "Authenticated admins update Joel media" on storage.objects;
create policy "Authenticated admins update Joel media" on storage.objects for update to authenticated using (bucket_id='joel-site-media') with check (bucket_id='joel-site-media');
drop policy if exists "Authenticated admins delete Joel media" on storage.objects;
create policy "Authenticated admins delete Joel media" on storage.objects for delete to authenticated using (bucket_id='joel-site-media');

